from itertools import permutations
A=[{(1,1),(4,4)}, {(1,1),(1,4),(4,1),(4,4)}, {(1,1),(4,1),(4,4)}, {(1,1)}]
M={9:{(1,1),(1,2),(1,3),(1,4),(3,1),(3,2),(3,4),(4,1),(4,2),(4,4)},6:{(1,1),(1,2),(1,4),(3,1),(3,2),(3,4),(4,1),(4,2),(4,4)},1:{(4,1),(4,3),(4,4)},8:{(r,c) for r in range(1,5) for c in range(1,5)}}
for i,a in enumerate(A): print(i,{k:len(a&m)/(len(a|m)) for k,m in M.items()})
vals=[]
ks=list(M)
for p in permutations(ks):
    sc=sum(len(a&M[k])/len(a|M[k]) for a,k in zip(A,p))
    vals.append((sc,p))
print(sorted(vals,reverse=True)[:10])

# compare similarity objectives for test assignment, list top via symmetric diff and inclusion
from itertools import permutations
klist=[9,6,1,8]
for metric in ['symdiff','precision','overlap']:
 vals=[]
 for p in permutations(klist):
  if metric=='symdiff': score=-sum(len(a^M[k]) for a,k in zip(A,p))
  elif metric=='precision': score=sum(len(a&M[k])/len(a) for a,k in zip(A,p))
  else: score=sum(len(a&M[k]) for a,k in zip(A,p))
  vals.append((score,p))
 print(metric, sorted(vals,reverse=True)[:5])
